-- 130: Original BrillaPrep WASSCE Applied Electricity syllabus evidence beta questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_021', 'topic_was_elect_5', 'subj_wassce_elect_app', 'exam_wassce', 'What energy conversion occurs in an electric motor?', 'multiple_choice', '["A. Electrical energy to mechanical energy","B. Mechanical energy to electrical energy","C. Thermal energy to nuclear energy","D. Chemical energy directly to light only"]', 'A', 'Motor conductors carrying current in a magnetic field experience force, producing torque and mechanical output. Therefore the correct answer is A: Electrical energy to mechanical energy.', 'hard', 1, 1, 90, 'st_was_elect_5', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_022', 'topic_was_elect_5', 'subj_wassce_elect_app', 'exam_wassce', 'What energy conversion occurs in a generator?', 'multiple_choice', '["A. Electrical energy to stored chemical energy only","B. Mechanical energy to electrical energy","C. Light energy to mass","D. Resistance to magnetic charge"]', 'B', 'A prime mover changes magnetic flux linkage with windings, inducing an emf and converting mechanical input to electrical output. Therefore the correct answer is B: Mechanical energy to electrical energy.', 'easy', 2, 2, 90, 'st_was_elect_5', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_023', 'topic_was_elect_5', 'subj_wassce_elect_app', 'exam_wassce', 'What is the function of the split-ring commutator in a simple DC motor?', 'multiple_choice', '["A. Increase supply frequency","B. Store charge like a capacitor","C. Reverse armature current each half-turn to maintain torque direction","D. Disconnect the magnetic field permanently"]', 'C', 'The commutator changes current direction relative to the field so the forces continue to turn the armature in the same rotational direction. Therefore the correct answer is C: Reverse armature current each half-turn to maintain torque direction.', 'medium', 1, 1, 90, 'st_was_elect_5', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_024', 'topic_was_elect_5', 'subj_wassce_elect_app', 'exam_wassce', 'Why is a starter used with many motors?', 'multiple_choice', '["A. To remove the need for a supply","B. To make the rotor weightless","C. To prevent every mechanical fault","D. To limit excessive starting current and provide control or protection"]', 'D', 'At start, back emf may be low and current high. A starter controls energisation and can add overload or undervoltage protection. Therefore the correct answer is D: To limit excessive starting current and provide control or protection.', 'hard', 2, 2, 90, 'st_was_elect_5', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_025', 'topic_was_elect_5', 'subj_wassce_elect_app', 'exam_wassce', 'What mainly determines the synchronous speed of an AC machine?', 'multiple_choice', '["A. Supply frequency and number of poles","B. Only the colour of the windings","C. Bearing diameter alone","D. Insulation resistance only"]', 'A', 'Synchronous speed follows 120 times frequency divided by pole count, so higher pole count lowers speed at a fixed frequency. Therefore the correct answer is A: Supply frequency and number of poles.', 'easy', 3, 3, 90, 'st_was_elect_5', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_026', 'topic_was_elect_6', 'subj_wassce_elect_app', 'exam_wassce', 'How should an ammeter be connected to measure circuit current?', 'multiple_choice', '["A. In parallel across the supply","B. In series with the circuit branch","C. Across an open switch only","D. Without completing a current path"]', 'B', 'An ammeter must carry the branch current and has low internal resistance, so parallel connection could create a dangerous high current. Therefore the correct answer is B: In series with the circuit branch.', 'medium', 2, 2, 90, 'st_was_elect_6', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_027', 'topic_was_elect_6', 'subj_wassce_elect_app', 'exam_wassce', 'How should a voltmeter be connected?', 'multiple_choice', '["A. In series with every load","B. Directly across a current transformer secondary left open","C. In parallel across the two points","D. Only to earth with no second lead"]', 'C', 'A voltmeter measures potential difference and has high internal resistance, so it is connected across the component or points of interest. Therefore the correct answer is C: In parallel across the two points.', 'hard', 1, 1, 90, 'st_was_elect_6', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_028', 'topic_was_elect_6', 'subj_wassce_elect_app', 'exam_wassce', 'What does a continuity test determine?', 'multiple_choice', '["A. The exact power factor of a live installation","B. The colour code of every cable","C. The future lifetime of a motor","D. Whether a low-resistance conducting path exists"]', 'D', 'With the circuit safely isolated, a continuity test checks whether conductors and connections form an unbroken path. Therefore the correct answer is D: Whether a low-resistance conducting path exists.', 'easy', 2, 2, 90, 'st_was_elect_6', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_029', 'topic_was_elect_6', 'subj_wassce_elect_app', 'exam_wassce', 'Why must resistance normally be measured on a de-energised circuit?', 'multiple_choice', '["A. The meter supplies its own test current and external voltage can damage it or mislead the reading","B. Resistance exists only when power is off","C. An ohmmeter generates mains voltage","D. Isolation makes every resistance zero"]', 'A', 'Ohmmeters use an internal source; applying them to live circuits creates unsafe conditions and invalid or damaging current paths. Therefore the correct answer is A: The meter supplies its own test current and external voltage can damage it or mislead the reading.', 'medium', 1, 1, 90, 'st_was_elect_6', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_030', 'topic_was_elect_6', 'subj_wassce_elect_app', 'exam_wassce', 'What is the purpose of an insulation-resistance test?', 'multiple_choice', '["A. Measure rotational speed","B. Assess resistance between conductors and earth or other conductors","C. Set the supply frequency","D. Determine the price of electricity"]', 'B', 'High insulation resistance indicates that unintended leakage paths are limited, while low readings may identify moisture, damage or contamination. Therefore the correct answer is B: Assess resistance between conductors and earth or other conductors.', 'hard', 3, 3, 90, 'st_was_elect_6', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to published WAEC Ghana Applied Electricity evidence; not official WAEC examination material.', 'https://waecgh.org/wp-content/uploads/2023/12/Technical17.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_elect_b001_021' AND 'q_was_elect_b001_030';
